#include "PluginProcessor.h"
#include <cstdio>
#include <cmath>
using namespace juce;
static double render(SynthMavenProcessor&p,double rate,int block){p.prepareToPlay(rate,block);AudioBuffer<float>b(2,block);MidiBuffer midi;double energy=0;int blocks=juce::jmax(32,8192/block);for(int n=0;n<blocks;n++){if(n==0)midi.addEvent(MidiMessage::noteOn(1,60,(uint8)100),0);if(n==blocks-2)midi.addEvent(MidiMessage::noteOff(1,60),0);p.processBlock(b,midi);for(int c=0;c<2;c++)for(int i=0;i<block;i++){float x=b.getSample(c,i);if(!std::isfinite(x))std::abort();energy+=std::abs(x);}}p.releaseResources();return energy;}
int main(int argc,char**argv){ScopedJuceInitialiser_GUI init;SynthMavenProcessor p;printf("%d factory sounds; %d exposed parameters\n",p.getNumPrograms(),p.getParameters().size());for(double rate:{44100.,48000.,88200.,96000.,192000.})for(int block:{1,32,127,512,1024}){double e=render(p,rate,block);if(e<=0){fprintf(stderr,"Silent rate %f block %d\n",rate,block);return 1;}}for(int n=0;n<p.getNumPrograms();n++){p.setCurrentProgram(n);render(p,48000,256);}p.setCurrentProgram(269);auto*param=p.parameters.getParameter("p96");param->setValueNotifyingHost(.73f);MemoryBlock state;p.getStateInformation(state);SynthMavenProcessor q;q.setStateInformation(state.getData(),(int)state.getSize());if(q.getCurrentProgram()!=269||std::abs(q.parameters.getRawParameterValue("p96")->load()-.73f)>.0001f)return 2;MemoryBlock again;q.getStateInformation(again);if(state!=again)return 3;
 if(argc>2){String error;File bank(argv[2]);auto names=SynthMavenProcessor::dx7VoiceNames(bank,error);if(names.size()!=32)return 4;for(int voice=0;voice<32;voice++){if(!p.loadPreset(bank,error,voice))return 5;if(p.displayName()!=names[voice])return 6;render(p,48000,256);}MemoryBlock imported;p.getStateInformation(imported);q.setStateInformation(imported.getData(),(int)imported.getSize());if(q.displayName()!=names[31])return 7;render(q,96000,127);p.setCurrentProgram(269);printf("PASS: 32 DX7 voices import, render and project recall\n");}
 if(argc>1){std::unique_ptr<AudioProcessorEditor> editor(p.createEditor());Image image(Image::ARGB,editor->getWidth(),editor->getHeight(),true);Graphics g(image);editor->paintEntireComponent(g,true);File file(argv[1]);auto stream=file.createOutputStream();stream->setPosition(0);stream->truncate();PNGImageFormat png;png.writeImageToStream(image,*stream);}
 puts("PASS: all presets; 5 rates × 5 block sizes; parameter and program recall; GUI construction");return 0;}
